1	package chainledger
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// This file is the regression net for the independence of comparison reports
12	// returned by CompareSnapshots. A Go caller keeps processing a returned report
13	// — deleting entries it does not care about, reordering lists for display, or
14	// rewriting a name — may hold several reports of the same snapshot pair at
15	// once (as well as reports for other pairs), and keeps holding both input
16	// snapshots. Every report must be this comparison alone:
17	//
18	//   - when several datasets common to both versions reached one shared root
19	//     set in the old version and another shared root set in the new version
20	//     (the two sets intersecting), each root-source entry keeps its own
21	//     accurate old/new root names: rewriting one entry's old roots, new roots,
22	//     or dataset name reaches neither the other entries nor that entry's
23	//     other side; a root reached by several paths is still listed once;
24	//   - a downstream whose DIRECT upstreams did not change still keeps its own
25	//     root-source change when an upstream adjustment moved its root set;
26	//   - two reports of the same legal pair never alias: rewriting, reordering,
27	//     or pruning any of the six lists in one leaves the other representing
28	//     the complete original diff, and both input snapshots keep their names,
29	//     direct upstream relations, content identifiers, and serialized bytes;
30	//     comparing the same pair again reproduces the original report byte for
31	//     byte;
32	//   - after a report is returned the caller may edit the snapshot records it
33	//     holds or compare a different legal pair; the earlier report's recorded
34	//     diff never moves (the compare interface gains no new corrupted-snapshot
35	//     behavior — only already returned results are pinned);
36	//   - a comparison with no diff gets its own empty result with every list
37	//     serialized as [], never entries left over from an earlier comparison;
38	//   - name casing and surrounding spaces are kept verbatim and the existing
39	//     ordering of sources, datasets, and relations is unchanged, while record
40	//     order and duplicate upstreams in legal inputs cannot move an unedited
41	//     report's content or JSON bytes.
42	//
43	// The deliberately edited report a caller keeps for display is out of scope:
44	// nothing repairs it or recomputes its lists.
45	
46	// intersectRootsOldGraph is the headline fixture: three roots R1 R2 R3, two
47	// old intermediates a1/a2, one shared node depending on both intermediates,
48	// and two downstreams D1 and D2. shared is reached by more than one path from
49	// every root (and D1 additionally depends directly on a1), so each root must
50	// still be listed exactly once. Every one of shared, D1, D2 reaches the same
51	// old root set {R1,R2,R3}.
52	const intersectRootsOldGraph = `{"datasets":[
53		{"name":"R1","upstreams":[]},
54		{"name":"R2","upstreams":[]},
55		{"name":"R3","upstreams":[]},
56		{"name":"a1","upstreams":["R1","R2"]},
57		{"name":"a2","upstreams":["R2","R3"]},
58		{"name":"shared","upstreams":["a1","a2"]},
59		{"name":"D1","upstreams":["a1","shared"]},
60		{"name":"D2","upstreams":["shared"]}
61	]}`
62	
63	// intersectRootsNewGraph keeps R2 and R3 (the intersection with the old root
64	// set), drops R1/a1/a2, adds R4/b1/b2, and repoints shared at the new
65	// intermediates. shared, D1, and D2 now reach the same new root set
66	// {R2,R3,R4}. D2's DIRECT upstream stays [shared] on both sides, so it is the
67	// downstream whose roots moved purely because of the upstream adjustment.
68	const intersectRootsNewGraph = `{"datasets":[
69		{"name":"R2","upstreams":[]},
70		{"name":"R3","upstreams":[]},
71		{"name":"R4","upstreams":[]},
72		{"name":"b1","upstreams":["R2","R4"]},
73		{"name":"b2","upstreams":["R3","R4"]},
74		{"name":"shared","upstreams":["b1","b2"]},
75		{"name":"D1","upstreams":["b1","shared"]},
76		{"name":"D2","upstreams":["shared"]}
77	]}`
