80	// entries, sorted by dataset name byte order.
81	var wantIntersectRootChanges = []RootSourceChange{
82		{Dataset: "D1", OldRoots: []string{"R1", "R2", "R3"}, NewRoots: []string{"R2", "R3", "R4"}},
83		{Dataset: "D2", OldRoots: []string{"R1", "R2", "R3"}, NewRoots: []string{"R2", "R3", "R4"}},
84		{Dataset: "shared", OldRoots: []string{"R1", "R2", "R3"}, NewRoots: []string{"R2", "R3", "R4"}},
85	}
