87	// rootChangeFor finds the root-source entry for dataset in report.
88	func rootChangeFor(report *CompareReport, dataset string) (RootSourceChange, bool) {
89		for _, change := range report.RootSourceChanges {
90			if change.Dataset == dataset {
91				return change, true
92			}
93		}
94		return RootSourceChange{}, false
