108	// TestCompareSharedRootSetEntriesAreAccurateAndSorted pins the business
109	// result of the headline fixture before any independence edit: three common
110	// datasets move between two overlapping root sets, and each entry records the
111	// exact sorted, once-only old and new root names. D2 has unchanged direct
112	// upstreams and must not appear in changedDatasets, but its root-source change
113	// is still recorded.
114	func TestCompareSharedRootSetEntriesAreAccurateAndSorted(t *testing.T) {
115		oldSnap := snapshotOf(t, intersectRootsOldGraph)
116		newSnap := snapshotOf(t, intersectRootsNewGraph)
117		report := CompareSnapshots(oldSnap, newSnap)
118	
119		if got, want := report.NewDatasets, []string{"R4", "b1", "b2"}; !reflect.DeepEqual(got, want) {
120			t.Errorf("NewDatasets = %v, want %v", got, want)
121		}
122		if got, want := report.RemovedDatasets, []string{"R1", "a1", "a2"}; !reflect.DeepEqual(got, want) {
123			t.Errorf("RemovedDatasets = %v, want %v", got, want)
124		}
125		// D1 gains b1 and loses a1 as a direct upstream; shared is fully repointed;
126		// D2 keeps [shared] directly even though its root set moves.
127		if got, want := report.ChangedDatasets, []string{"D1", "shared"}; !reflect.DeepEqual(got, want) {
128			t.Errorf("ChangedDatasets = %v, want %v", got, want)
129		}
130		if got, want := report.AddedRelations, []Relation{
131			{Upstream: "R2", Downstream: "b1"},
132			{Upstream: "R3", Downstream: "b2"},
133			{Upstream: "R4", Downstream: "b1"},
134			{Upstream: "R4", Downstream: "b2"},
135			{Upstream: "b1", Downstream: "D1"},
136			{Upstream: "b1", Downstream: "shared"},
137			{Upstream: "b2", Downstream: "shared"},
138		}; !reflect.DeepEqual(got, want) {
139			t.Errorf("AddedRelations = %v, want %v", got, want)
140		}
141		if got, want := report.RemovedRelations, []Relation{
142			{Upstream: "R1", Downstream: "a1"},
143			{Upstream: "R2", Downstream: "a1"},
144			{Upstream: "R2", Downstream: "a2"},
145			{Upstream: "R3", Downstream: "a2"},
146			{Upstream: "a1", Downstream: "D1"},
147			{Upstream: "a1", Downstream: "shared"},
148			{Upstream: "a2", Downstream: "shared"},
149		}; !reflect.DeepEqual(got, want) {
150			t.Errorf("RemovedRelations = %v, want %v", got, want)
151		}
152	
153		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantIntersectRootChanges) {
154			t.Fatalf("RootSourceChanges = %v\nwant %v", got, wantIntersectRootChanges)
155		}
156	
157		// Every root reachable by several paths is still listed exactly once.
158		for _, change := range report.RootSourceChanges {
159			if seen := dupNames(change.OldRoots); len(seen) != 0 {
160				t.Errorf("%s OldRoots lists roots more than once: %v in %v", change.Dataset, seen, change.OldRoots)
161			}
162			if seen := dupNames(change.NewRoots); len(seen) != 0 {
163				t.Errorf("%s NewRoots lists roots more than once: %v in %v", change.Dataset, seen, change.NewRoots)
164			}
165		}
166	}
