168	// TestCompareRootSourceEntriesAreIndependentOfEachOther is the headline
169	// aliasing guarantee: when several root-source entries start with identical
170	// old and new root arrays (because the datasets moved between the same two
171	// overlapping root sets), every display edit a caller makes on ONE entry —
172	// its old roots, its new roots, or its dataset name — changes only that
173	// entry. The other entries keep both of their root arrays exactly, and the
174	// edited entry's other side is untouched too. A separately returned report of
175	// the same pair stays the complete original diff.
176	func TestCompareRootSourceEntriesAreIndependentOfEachOther(t *testing.T) {
177		editKinds := map[string]func(*RootSourceChange){
178			"rewrite old roots in place and append": func(c *RootSourceChange) {
179				c.OldRoots[0] = "HACK"
180				c.OldRoots = append(c.OldRoots, "GHOST")
181			},
182			"rewrite new roots in place and append": func(c *RootSourceChange) {
183				c.NewRoots[0] = "HACK"
184				c.NewRoots = append(c.NewRoots, "GHOST")
185			},
186			"rename the dataset": func(c *RootSourceChange) {
187				c.Dataset = "HACK"
188			},
189		}
190		for _, target := range []string{"D1", "D2", "shared"} {
191			for editName, edit := range editKinds {
192				t.Run(target+"/"+editName, func(t *testing.T) {
193					oldSnap := snapshotOf(t, intersectRootsOldGraph)
194					newSnap := snapshotOf(t, intersectRootsNewGraph)
195					report := CompareSnapshots(oldSnap, newSnap)
196					// An independently returned report of the same pair is the
197					// oracle for everything not deliberately edited.
198					oracle := CompareSnapshots(snapshotOf(t, intersectRootsOldGraph), snapshotOf(t, intersectRootsNewGraph))
199	
200					idx := indexOfRootChange(report, target)
201					if idx < 0 {
202						t.Fatalf("report has no root-source entry for %q", target)
203					}
204					otherSideBefore := struct{ old, new []string }{
205						old: append([]string(nil), report.RootSourceChanges[idx].OldRoots...),
206						new: append([]string(nil), report.RootSourceChanges[idx].NewRoots...),
207					}
208					// Edit the entry through its slice position the way a caller
209					// reorganizing a held report does.
210					edit(&report.RootSourceChanges[idx])
211					editedName := target
212					if editName == "rename the dataset" {
213						editedName = "HACK"
214					}
215	
216					// Every OTHER dataset keeps both of its root arrays exactly as
217					// originally reported.
218					for _, want := range wantIntersectRootChanges {
219						if want.Dataset == target {
220							continue
221						}
222						got, ok := rootChangeFor(report, want.Dataset)
223						if !ok {
224							t.Fatalf("entry for %q vanished after editing %q", want.Dataset, target)
225						}
226						if !reflect.DeepEqual(got, want) {
227							t.Errorf("entry for %q changed when %q was edited:\n got %+v\nwant %+v", want.Dataset, target, got, want)
228						}
229					}
230	
231					// The edited entry's OTHER side is untouched (the edit must not
232					// share backing storage between old and new root arrays).
233					gotEdited, ok := rootChangeFor(report, editedName)
234					if !ok {
235						t.Fatalf("edited entry for %q vanished (renamed=%v)", target, editedName)
236					}
237					if editName != "rewrite old roots in place and append" {
238						if !reflect.DeepEqual(gotEdited.OldRoots, otherSideBefore.old) {
239							t.Errorf("edited entry OldRoots = %v, want untouched %v", gotEdited.OldRoots, otherSideBefore.old)
240						}
241					}
242					if editName != "rewrite new roots in place and append" {
243						if !reflect.DeepEqual(gotEdited.NewRoots, otherSideBefore.new) {
244							t.Errorf("edited entry NewRoots = %v, want untouched %v", gotEdited.NewRoots, otherSideBefore.new)
245						}
246					}
247	
248					// The independently returned report is the complete original.
249					if !reflect.DeepEqual(oracle.RootSourceChanges, wantIntersectRootChanges) {
250						t.Errorf("separate report root changes = %v, want %v", oracle.RootSourceChanges, wantIntersectRootChanges)
251					}
252					// The input snapshots are untouched too.
253					if got := snapshotDatasetsCopy(oldSnap); !reflect.DeepEqual(got, snapshotDatasetsCopy(snapshotOf(t, intersectRootsOldGraph))) {
254						t.Errorf("old snapshot changed after editing a report entry: %v", got)
255					}
256					if got := snapshotDatasetsCopy(newSnap); !reflect.DeepEqual(got, snapshotDatasetsCopy(snapshotOf(t, intersectRootsNewGraph))) {
257						t.Errorf("new snapshot changed after editing a report entry: %v", got)
258					}
259				})
260			}
261		}
262	}
