264	// indexOfRootChange returns the first index of an entry whose Dataset equals
265	// name, or -1.
266	func indexOfRootChange(report *CompareReport, name string) int {
267		for i := range report.RootSourceChanges {
268			if report.RootSourceChanges[i].Dataset == name {
269				return i
270			}
271		}
272		return -1
273	}
