275	// TestCompareTwoReportsOfSamePairAreIndependent thoroughly edits one report
276	// (in-place rewrites, appends, swaps, and pruning across every list kind) and
277	// verifies the other report still describes the complete original diff, while
278	// both input snapshots keep names, upstreams, content ids, and export bytes.
279	// Comparing the same pair again afterwards reproduces the original report,
280	// including its JSON bytes.
281	func TestCompareTwoReportsOfSamePairAreIndependent(t *testing.T) {
282		oldSnap := snapshotOf(t, intersectRootsOldGraph)
283		newSnap := snapshotOf(t, intersectRootsNewGraph)
284		first := CompareSnapshots(oldSnap, newSnap)
285		second := CompareSnapshots(oldSnap, newSnap)
286		oracle := CompareSnapshots(snapshotOf(t, intersectRootsOldGraph), snapshotOf(t, intersectRootsNewGraph))
287	
288		wantBytes := mustMarshalCompareReport(t, oracle)
289		oldBytesBefore := mustMarshalSnapshot(t, oldSnap)
290		newBytesBefore := mustMarshalSnapshot(t, newSnap)
291		oldDatasetsBefore := snapshotDatasetsCopy(oldSnap)
292		newDatasetsBefore := snapshotDatasetsCopy(newSnap)
293		oldID, newID := oldSnap.ContentID, newSnap.ContentID
294	
295		// Rewrite, reorder, append, and prune every list kind in the first report.
296		first.NewDatasets[0] = "HACK"
297		first.NewDatasets = append(first.NewDatasets, "GHOST")
298		first.RemovedDatasets[0], first.RemovedDatasets[len(first.RemovedDatasets)-1] =
299			first.RemovedDatasets[len(first.RemovedDatasets)-1], first.RemovedDatasets[0]
300		first.RemovedDatasets[1] = "HACK"
301		first.ChangedDatasets = first.ChangedDatasets[:1]
302		first.ChangedDatasets[0] = "HACK"
303		first.AddedRelations[0], first.AddedRelations[1] = first.AddedRelations[1], first.AddedRelations[0]
304		first.AddedRelations[0].Upstream = "HACK"
305		first.AddedRelations[0].Downstream = "GHOST"
306		first.AddedRelations = append(first.AddedRelations, Relation{Upstream: "FAKE", Downstream: "FAKE"})
307		first.RemovedRelations = first.RemovedRelations[:2]
308		first.RemovedRelations[1].Downstream = "GHOST"
309		// Swap the root-change entries, edit through the swapped position, prune.
310		first.RootSourceChanges[0], first.RootSourceChanges[2] = first.RootSourceChanges[2], first.RootSourceChanges[0]
311		first.RootSourceChanges[0].OldRoots[0] = "HACK"
312		first.RootSourceChanges[0].NewRoots = append(first.RootSourceChanges[0].NewRoots, "GHOST")
313		first.RootSourceChanges[0].Dataset = "DISPLAY"
314		first.RootSourceChanges = first.RootSourceChanges[:1]
315	
316		// The edit really landed on the first copy.
317		if !reflect.DeepEqual(first.RootSourceChanges, []RootSourceChange{
318			{Dataset: "DISPLAY", OldRoots: []string{"HACK", "R2", "R3"}, NewRoots: []string{"R2", "R3", "R4", "GHOST"}},
319		}) {
320			t.Fatalf("test setup: first report edit had no expected effect: %+v", first.RootSourceChanges)
321		}
322	
323		// The untouched report is the complete original diff.
324		if !reflect.DeepEqual(second, oracle) {
325			t.Errorf("second report differs from the original after editing the first:\n got %#v\nwant %#v", second, oracle)
326		}
327		if got := mustMarshalCompareReport(t, second); !bytes.Equal(got, wantBytes) {
328			t.Errorf("second report JSON moved with the first:\n got %s\nwant %s", got, wantBytes)
329		}
330	
331		// Both input snapshots are unchanged: content id, graph records, bytes.
332		if oldSnap.ContentID != oldID || newSnap.ContentID != newID {
333			t.Errorf("an input content id moved: old=%q want %q, new=%q want %q",
334				oldSnap.ContentID, oldID, newSnap.ContentID, newID)
335		}
336		if got := snapshotDatasetsCopy(oldSnap); !reflect.DeepEqual(got, oldDatasetsBefore) {
337			t.Errorf("old snapshot records changed during/after comparison:\n got %v\nwant %v", got, oldDatasetsBefore)
338		}
339		if got := snapshotDatasetsCopy(newSnap); !reflect.DeepEqual(got, newDatasetsBefore) {
340			t.Errorf("new snapshot records changed during/after comparison:\n got %v\nwant %v", got, newDatasetsBefore)
341		}
342		if got := mustMarshalSnapshot(t, oldSnap); !bytes.Equal(got, oldBytesBefore) {
343			t.Errorf("old snapshot bytes changed:\n got %s\nwant %s", got, oldBytesBefore)
344		}
345		if got := mustMarshalSnapshot(t, newSnap); !bytes.Equal(got, newBytesBefore) {
346			t.Errorf("new snapshot bytes changed:\n got %s\nwant %s", got, newBytesBefore)
347		}
348	
349		// Comparing the same pair again still reproduces the original result and
350		// its exact JSON bytes.
351		again := CompareSnapshots(oldSnap, newSnap)
352		if !reflect.DeepEqual(again, oracle) {
353			t.Errorf("re-comparison differs from the original report:\n got %#v\nwant %#v", again, oracle)
354		}
355		if got := mustMarshalCompareReport(t, again); !bytes.Equal(got, wantBytes) {
356			t.Errorf("re-comparison JSON differs:\n got %s\nwant %s", got, wantBytes)
357		}
358	}
