412	// TestCompareEmptyResultIsIndependentAndCarriesNoResidue verifies that a diff
413	// with no changes gets its own fresh result: after a non-empty comparison, the
414	// empty lists are zero-length, non-nil, serialize as [], and contain no name
415	// seen in the earlier report. Editing either empty report afterwards cannot
416	// move the other one, and a further identical comparison stays empty.
417	func TestCompareEmptyResultIsIndependentAndCarriesNoResidue(t *testing.T) {
418		oldSnap := snapshotOf(t, intersectRootsOldGraph)
419		newSnap := snapshotOf(t, intersectRootsNewGraph)
420		nonEmpty := CompareSnapshots(oldSnap, newSnap)
421		if len(nonEmpty.RootSourceChanges) == 0 {
422			t.Fatalf("test setup: headline comparison produced no changes")
423		}
424		// Display-edit the non-empty report; residue must not leak from it either.
425		nonEmpty.RootSourceChanges[0].OldRoots[0] = "HACK"
426		nonEmpty.NewDatasets = append(nonEmpty.NewDatasets, "GHOST")
427	
428		identical := snapshotOf(t, intersectRootsOldGraph)
429		empty := CompareSnapshots(identical, identical)
430		assertEmptyReport(t, empty)
431	
432		emptyJSON := string(mustMarshalCompareReport(t, empty))
433		for _, key := range []string{`"newDatasets":`, `"removedDatasets":`, `"changedDatasets":`, `"addedRelations":`, `"removedRelations":`, `"rootSourceChanges":`} {
434			if !strings.Contains(emptyJSON, key+"[]") {
435				t.Errorf("empty report key %s not encoded as []:\n%s", key, emptyJSON)
436			}
437		}
438		for _, leftover := range []string{"R1", "R4", "shared", "b1", "a2", "HACK", "GHOST"} {
439			if strings.Contains(emptyJSON, leftover) {
440				t.Errorf("empty report carries a leftover entry %q from an earlier comparison:\n%s", leftover, emptyJSON)
441			}
442		}
443	
444		// Two empty results are independent as well: appending a display entry to
445		// one must not give the other any content.
446		emptyToo := CompareSnapshots(identical, identical)
447		empty.NewDatasets = append(empty.NewDatasets, "GHOST")
448		empty.RootSourceChanges = append(empty.RootSourceChanges, RootSourceChange{Dataset: "FAKE"})
449		assertEmptyReport(t, emptyToo)
450	
451		// A further identical comparison, after the edits, is still its own empty
452		// result with the same JSON bytes.
453		emptyAgain := CompareSnapshots(identical, identical)
454		assertEmptyReport(t, emptyAgain)
455		if got := mustMarshalCompareReport(t, emptyAgain); !strings.Contains(string(got), `"rootSourceChanges":[]`) {
456			t.Errorf("repeated empty comparison did not encode []:\n%s", got)
457		}
458	}
