460	// TestCompareReportBytesUnaffectedByRecordOrderAndDuplicates feeds the
461	// headline scenario in shuffled form with shuffled and repeated upstreams;
462	// the unedited report must come out content- and byte-identical to the
463	// canonical comparison, with verbatim case/space name spellings in the
464	// root-source entries and the existing byte-order sorting on every list.
465	func TestCompareReportBytesUnaffectedByRecordOrderAndDuplicates(t *testing.T) {
