467		newCanonical := snapshotOf(t, intersectRootsNewGraph)
468		wantBytes := mustMarshalCompareReport(t, CompareSnapshots(oldCanonical, newCanonical))
469		oldBytesBefore := mustMarshalSnapshot(t, oldCanonical)
470		newBytesBefore := mustMarshalSnapshot(t, newCanonical)
471	
472		// Same semantics as the headline fixtures: records shuffled, upstream
473		// lists shuffled and repeated, including D1's multipath dependency.
474		oldShuffled := snapshotOf(t, `{"datasets":[
475			{"name":"D2","upstreams":["shared"]},
476			{"upstreams":["shared","a1","a1"],"name":"D1"},
477			{"upstreams":["a2","a1","a2"],"name":"shared"},
478			{"name":"a2","upstreams":["R3","R2"]},
479			{"upstreams":["R2","R1","R1"],"name":"a1"},
480			{"name":"R3","upstreams":[]},
481			{"name":"R2","upstreams":[]},
482			{"name":"R1","upstreams":[]}
483		]}`)
484		newShuffled := snapshotOf(t, `{"datasets":[
485			{"upstreams":["shared"],"name":"D2"},
486			{"name":"D1","upstreams":["shared","b1","b1"]},
487			{"upstreams":["b2","b1","b2"],"name":"shared"},
488			{"upstreams":["R4","R3"],"name":"b2"},
489			{"name":"b1","upstreams":["R4","R2","R2"]},
490			{"name":"R4","upstreams":[]},
491			{"name":"R3","upstreams":[]},
492			{"name":"R2","upstreams":[]}
493		]}`)
494	
495		report := CompareSnapshots(oldShuffled, newShuffled)
496		if got := mustMarshalCompareReport(t, report); !bytes.Equal(got, wantBytes) {
497			t.Fatalf("shuffled/duplicated inputs produced a different report:\n got %s\nwant %s", got, wantBytes)
498		}
499		if !reflect.DeepEqual(report.RootSourceChanges, wantIntersectRootChanges) {
500			t.Errorf("shuffled inputs root changes = %v, want %v", report.RootSourceChanges, wantIntersectRootChanges)
501		}
502	
503		// Comparison stayed read-only on the canonical snapshots handed in.
504		if got := mustMarshalSnapshot(t, oldCanonical); !bytes.Equal(got, oldBytesBefore) {
505			t.Errorf("old snapshot bytes changed during comparison:\n got %s\nwant %s", got, oldBytesBefore)
506		}
507		if got := mustMarshalSnapshot(t, newCanonical); !bytes.Equal(got, newBytesBefore) {
508			t.Errorf("new snapshot bytes changed during comparison:\n got %s\nwant %s", got, newBytesBefore)
509		}
510	
511		// Editing the shuffled-input report's first entry cannot rewrite the
512		// verbatim spellings a second report carries — here with case/space names.
513		caseOld := snapshotOf(t, `{"datasets":[
514			{"name":" A ","upstreams":[]},
515			{"name":"a","upstreams":[]},
516			{"name":"A","upstreams":[]},
517			{"name":"M","upstreams":[" A ","a"]},
518			{"name":"n","upstreams":["M"]}
519		]}`)
520		caseNew := snapshotOf(t, `{"datasets":[
521			{"name":" A ","upstreams":[]},
522			{"name":"a","upstreams":[]},
523			{"name":"A","upstreams":[]},
524			{"name":"M","upstreams":["A"]},
525			{"name":"n","upstreams":["M"]}
526		]}`)
527		first := CompareSnapshots(caseOld, caseNew)
528		second := CompareSnapshots(caseOld, caseNew)
529		secondBytes := mustMarshalCompareReport(t, second)
530		wantCaseChanges := []RootSourceChange{
531			{Dataset: "M", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A"}},
532			{Dataset: "n", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A"}},
533		}
534		if !reflect.DeepEqual(first.RootSourceChanges, wantCaseChanges) {
535			t.Fatalf("case/space root changes = %v, want %v", first.RootSourceChanges, wantCaseChanges)
536		}
537		first.RootSourceChanges[0].OldRoots[0] = "trimmed"
538		first.RootSourceChanges[0].OldRoots = append(first.RootSourceChanges[0].OldRoots, "HACK")
539		first.RootSourceChanges[0].Dataset = "HACK"
540		if !reflect.DeepEqual(second.RootSourceChanges, wantCaseChanges) {
541			t.Errorf("case/space spellings moved into the other report: %v", second.RootSourceChanges)
542		}
543		if got := mustMarshalCompareReport(t, second); !bytes.Equal(got, secondBytes) {
544			t.Errorf("case/space report JSON changed after editing the first:\n got %s\nwant %s", got, secondBytes)
545		}
546	}
547	
548	// dupNames returns the names appearing more than once in list.
549	func dupNames(list []string) []string {
550		seen := make(map[string]int)
551		var dups []string
552		for _, name := range list {
553			seen[name]++
554			if seen[name] == 2 {
555				dups = append(dups, name)
556			}
557		}
558		return dups
559	}
