86	// rootChangeMap indexes a compare report's root-source changes by dataset.
87	func rootChangeMap(report *CompareReport) map[string]RootSourceChange {
88		byName := make(map[string]RootSourceChange, len(report.RootSourceChanges))
89		for _, change := range report.RootSourceChanges {
90			byName[change.Dataset] = change
91		}
92		return byName
