95	// assertTracePathsAreReal walks every reported path through adj and pins the
96	// path rules the comparison relies on: the path starts at the queried
97	// dataset, every consecutive pair is a real direct-upstream edge, only the
98	// final node is a root (intermediate nodes still have upstreams), roots are
99	// reported once, and entries are ordered by root name byte order.
100	func assertTracePathsAreReal(t *testing.T, report *TraceReport, adj adjacency) {
101		t.Helper()
102		seen := make(map[string]bool)
103		var prevRoot string
104		for i, src := range report.Sources {
105			if seen[src.Root] {
106				t.Errorf("root %q reported more than once for query %q", src.Root, report.Dataset)
107			}
108			seen[src.Root] = true
109			if i > 0 && src.Root <= prevRoot {
110				t.Errorf("sources for %q not in strict root byte order at %d: %q after %q", report.Dataset, i, src.Root, prevRoot)
111			}
112			prevRoot = src.Root
113			if len(src.Path) == 0 {
114				t.Errorf("root %q for query %q has an empty path", src.Root, report.Dataset)
115				continue
116			}
117			if src.Path[0] != report.Dataset {
118				t.Errorf("path to %q starts at %q, want queried dataset %q", src.Root, src.Path[0], report.Dataset)
119			}
120			if src.Path[len(src.Path)-1] != src.Root {
121				t.Errorf("path %v ends at %q, want its root %q", src.Path, src.Path[len(src.Path)-1], src.Root)
122			}
123			for j := 1; j < len(src.Path); j++ {
124				node, parent := src.Path[j-1], src.Path[j]
125				if !containsString(adj[node], parent) {
126					t.Errorf("path %v uses an edge that does not exist: %q -> %q", src.Path, node, parent)
127				}
128				if j < len(src.Path)-1 && len(adj[parent]) == 0 {
129					t.Errorf("path %v passes through root %q before its end", src.Path, parent)
130				}
131			}
132			if len(adj[src.Root]) != 0 {
133				t.Errorf("reported root %q still has upstreams %v", src.Root, adj[src.Root])
134			}
135		}
136	}
