374		}
375		// rootA itself still exists as a root in both versions and reaches only
376		// itself, so it is not a source change despite being lost downstream.
377		assertDatasetNotAChange(t, report, "rootA")
378		assertNameAbsentFromReport(t, report, "solo")
379	
380		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
381	}
382	
383	// TestTraceAndCompareCommonDatasetClearedToBecomeRoot covers a common dataset
384	// whose ENTIRE upstream set is cleared: in the new snapshot its trace returns
385	// only itself with a single-element path, the comparison's new root set is
386	// just its own name, and the dataset downstream of it (direct upstream
387	// unchanged) moves to the new root as well. The still-existing old root p is
388	// not removed from either version.
389	func TestTraceAndCompareCommonDatasetClearedToBecomeRoot(t *testing.T) {
390		oldSnap := snapshotOf(t, `{"datasets":[
391			{"name":"p","upstreams":[]},
392			{"name":"m","upstreams":["p"]},
393			{"name":"n","upstreams":["m"]},
394			{"name":"x","upstreams":[]}
395		]}`)
396		newSnap := snapshotOf(t, `{"datasets":[
397			{"name":"p","upstreams":[]},
398			{"name":"m","upstreams":[]},
399			{"name":"n","upstreams":["m"]},
400			{"name":"x","upstreams":[]}
401		]}`)
402	
403		report := CompareSnapshots(oldSnap, newSnap)
404		if got, want := report.ChangedDatasets, []string{"m"}; !reflect.DeepEqual(got, want) {
405			t.Errorf("ChangedDatasets = %v, want only %v", got, want)
406		}
407		if len(report.NewDatasets) != 0 || len(report.RemovedDatasets) != 0 {
408			t.Errorf("no node is added or removed, got new=%v removed=%v", report.NewDatasets, report.RemovedDatasets)
409		}
410		wantChanges := []RootSourceChange{
411			{Dataset: "m", OldRoots: []string{"p"}, NewRoots: []string{"m"}},
412			{Dataset: "n", OldRoots: []string{"p"}, NewRoots: []string{"m"}},
413		}
414		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantChanges) {
415			t.Fatalf("RootSourceChanges = %v, want %v", got, wantChanges)
416		}
417	
418		// The new root traces only itself as a single-element path.
419		if got, want := traceReportSources(t, newSnap, "m"), []SourceTrace{{Root: "m", Path: []string{"m"}}}; !reflect.DeepEqual(got, want) {
420			t.Errorf("new trace m = %+v, want single-element self path %+v", got, want)
421		}
422		// n still has an upstream, so m — not n — is its only root; the
423		// disconnected x never joins.
424		if got, want := traceReportSources(t, newSnap, "n"), []SourceTrace{{Root: "m", Path: []string{"n", "m"}}}; !reflect.DeepEqual(got, want) {
425			t.Errorf("new trace n = %+v, want %+v", got, want)
426		}
427		// Old traces are unchanged in meaning.
428		if got, want := traceReportSources(t, oldSnap, "n"), []SourceTrace{{Root: "p", Path: []string{"n", "m", "p"}}}; !reflect.DeepEqual(got, want) {
429			t.Errorf("old trace n = %+v, want %+v", got, want)
430		}
431	
432		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
433	}
434	
435	// versionOnlyOldGraph / versionOnlyNewGraph share p and keep but each carry
436	// datasets the other side lacks, including a short derivation chain that
437	// disappears or appears as a whole.
438	const versionOnlyOldGraph = `{"datasets":[
439		{"name":"p","upstreams":[]},
440		{"name":"keep","upstreams":[]},
441		{"name":"gone","upstreams":["p"]},
442		{"name":"g","upstreams":["gone"]}
443	]}`
444	
445	const versionOnlyNewGraph = `{"datasets":[
446		{"name":"p","upstreams":[]},
447		{"name":"keep","upstreams":[]},
448		{"name":"added","upstreams":["p"]},
449		{"name":"h","upstreams":["added"]}
450	]}`
