452	// TestTraceAndCompareVersionOnlyDatasetsStayOutOfSourceChanges pins the
453	// boundary: added/removed datasets are classified exactly once, never enter
454	// rootSourceChanges, and tracing them in the version that lacks them fails
455	// with no success report instead of returning fabricated roots.
456	func TestTraceAndCompareVersionOnlyDatasetsStayOutOfSourceChanges(t *testing.T) {
457		oldSnap := snapshotOf(t, versionOnlyOldGraph)
458		newSnap := snapshotOf(t, versionOnlyNewGraph)
