472		}
473	
474		// Names present in a version trace successfully there.
475		if got := traceRoots(t, oldSnap, "gone"); !reflect.DeepEqual(got, []string{"p"}) {
476			t.Errorf("old trace gone roots = %v, want [p]", got)
477		}
478		if got := traceRoots(t, oldSnap, "g"); !reflect.DeepEqual(got, []string{"p"}) {
479			t.Errorf("old trace g roots = %v, want [p]", got)
480		}
481		if got := traceRoots(t, newSnap, "added"); !reflect.DeepEqual(got, []string{"p"}) {
