507	// TestTraceAndCompareByteOrderCaseAndSpaceRoots pins the ordering the two
508	// reports share when roots differ only by case or surrounding spaces: names
509	// are kept verbatim and ordered by UTF-8 byte order (space 0x20, then "A"
510	// 0x41, then "a" 0x61), both in the trace's sources and in the comparison's
511	// oldRoots/newRoots. n's direct upstream ([M]) never changes; its root set
512	// moves purely because M was repointed.
513	func TestTraceAndCompareByteOrderCaseAndSpaceRoots(t *testing.T) {
514		oldSnap := snapshotOf(t, `{"datasets":[
515			{"name":" A ","upstreams":[]},
516			{"name":"A","upstreams":[]},
517			{"name":"a","upstreams":[]},
518			{"name":"M","upstreams":[" A ","a"]},
