521		newSnap := snapshotOf(t, `{"datasets":[
522			{"name":" A ","upstreams":[]},
523			{"name":"A","upstreams":[]},
524			{"name":"a","upstreams":[]},
525			{"name":"M","upstreams":["A","a"]},
526			{"name":"n","upstreams":["M"]}
527		]}`)
