529		report := CompareSnapshots(oldSnap, newSnap)
530		wantChanges := []RootSourceChange{
531			{Dataset: "M", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A", "a"}},
532			{Dataset: "n", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A", "a"}},
533		}
534		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantChanges) {
535			t.Fatalf("RootSourceChanges = %v, want %v", got, wantChanges)
536		}
537	
538		oldM := traceReportSources(t, oldSnap, "M")
539		if got, want := []string{oldM[0].Root, oldM[1].Root}, []string{" A ", "a"}; !reflect.DeepEqual(got, want) {
540			t.Errorf("old M root order = %v, want byte order %v", got, want)
541		}
542		newM := traceReportSources(t, newSnap, "M")
543		if got, want := []string{newM[0].Root, newM[1].Root}, []string{"A", "a"}; !reflect.DeepEqual(got, want) {
544			t.Errorf("new M root order = %v, want byte order %v", got, want)
545		}
546		// The spaced spelling and the single-letter casing are carried verbatim
547		// into the path arrays.
548		if got, want := newM[0].Path, []string{"M", "A"}; !reflect.DeepEqual(got, want) {
549			t.Errorf("new M path to A = %v, want %v", got, want)
550		}
551		if got := traceReportSources(t, newSnap, "n"); !reflect.DeepEqual(got, []SourceTrace{
552			{Root: "A", Path: []string{"n", "M", "A"}},
553			{Root: "a", Path: []string{"n", "M", "a"}},
554		}) {
555			t.Errorf("new n sources = %+v, want verbatim case/space paths", got)
556		}
557	
558		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
559	}
