561	// TestTraceAndCompareDeterministicAcrossShuffledSemantics feeds the root-loss
562	// scenario in shuffled form (records reordered, upstreams reordered and
563	// repeated) and requires both reports to be byte-identical to the canonical
564	// run, while both input snapshots keep their serialized bytes throughout.
565	func TestTraceAndCompareDeterministicAcrossShuffledSemantics(t *testing.T) {
566		oldCanonical := snapshotOf(t, branchOldGraph)
567		newCanonical := snapshotOf(t, `{"datasets":[
568			{"name":"rootA","upstreams":[]},
569			{"name":"rootB","upstreams":[]},
570			{"name":"rootC","upstreams":[]},
571			{"name":"a0","upstreams":["rootA"]},
572			{"name":"a1","upstreams":["rootB"]},
573			{"name":"a2","upstreams":["rootC"]},
574			{"name":"b1","upstreams":["rootB"]},
575			{"name":"merge","upstreams":["a1","a2","b1"]},
576			{"name":"down","upstreams":["merge"]},
577			{"name":"down2","upstreams":["down"]},
578			{"name":"solo","upstreams":[]}
579		]}`)
580		oldShuffled := snapshotOf(t, `{"datasets":[
581			{"upstreams":[],"name":"solo"},
582			{"name":"down2","upstreams":["down","down"]},
583			{"upstreams":["merge"],"name":"down"},
584			{"name":"merge","upstreams":["b1","a2","a1","a2"]},
585			{"upstreams":["rootB","rootB"],"name":"b1"},
586			{"name":"a2","upstreams":["rootC","rootA"]},
587			{"upstreams":["rootA"],"name":"a1"},
588			{"name":"a0","upstreams":["rootA"]},
589			{"name":"rootC","upstreams":[]},
590			{"name":"rootB","upstreams":[]},
591			{"name":"rootA","upstreams":[]}
592		]}`)
593		newShuffled := snapshotOf(t, `{ "datasets" : [
594			{"name":"solo","upstreams":[]},
595			{"upstreams":["down"],"name":"down2"},
596			{"name":"down","upstreams":["merge","merge"]},
597			{"upstreams":["a2","b1","a1"],"name":"merge"},
598			{"name":"b1","upstreams":["rootB"]},
599			{"name":"a2","upstreams":["rootC","rootC"]},
600			{"name":"a1","upstreams":["rootB"]},
601			{"name":"a0","upstreams":["rootA","rootA"]},
602			{"name":"rootC","upstreams":[]},
603			{"upstreams":[],"name":"rootB"},
604			{"upstreams":[],"name":"rootA"}
605		] }`)
606	
607		wantCompare, err := json.Marshal(CompareSnapshots(oldCanonical, newCanonical))
608		if err != nil {
609			t.Fatalf("marshal canonical compare: %v", err)
610		}
611		gotCompare, err := json.Marshal(CompareSnapshots(oldShuffled, newShuffled))
612		if err != nil {
613			t.Fatalf("marshal shuffled compare: %v", err)
614		}
615		if string(gotCompare) != string(wantCompare) {
616			t.Fatalf("compare reports differ for semantically equal pairs:\n got %s\nwant %s", gotCompare, wantCompare)
617		}
618	
619		// Every trace over the shuffled snapshots equals the canonical trace, both
620		// the root sets and the representative paths.
621		for _, name := range commonNamesIn(oldCanonical, newCanonical) {
622			wantOld, err := TraceSources(oldCanonical, name)
623			if err != nil {
624				t.Fatalf("canonical old trace %q: %v", name, err)
625			}
626			wantNew, err := TraceSources(newCanonical, name)
627			if err != nil {
628				t.Fatalf("canonical new trace %q: %v", name, err)
629			}
630			gotOld, err := TraceSources(oldShuffled, name)
631			if err != nil {
632				t.Fatalf("shuffled old trace %q: %v", name, err)
633			}
634			gotNew, err := TraceSources(newShuffled, name)
635			if err != nil {
