647		// before and after.
648		oldBytes, err := MarshalSnapshot(oldCanonical)
649		if err != nil {
650			t.Fatalf("marshal old: %v", err)
651		}
652		newBytes, err := MarshalSnapshot(newCanonical)
653		if err != nil {
654			t.Fatalf("marshal new: %v", err)
655		}
656		_ = CompareSnapshots(oldCanonical, newCanonical)
657		for _, name := range commonNamesIn(oldCanonical, newCanonical) {
658			if _, err := TraceSources(oldCanonical, name); err != nil {
